#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
	
	ll t; cin >> t;
	
	while(t--){
	    ll n, k; cin >>n >> k;
	    
	    string s; cin >> s;
	    
	    ll val1 = 0, val2 = 0, flag = 0, f1 = 0, f2 = 0;
	    for(ll i = 0; i < n; i++){
	        if(s[i] == 'G' && !f1 ) f1= 1;
	        else if(s[i] == 'G' && !f2 && k-val1 == 0) f2 =1;
	        else if(s[i] == 'I' && (!f1 || !f2)){continue;}
	        else if(s[i] == 'G' && k-val1 >= 1) val1++;
	        else if(s[i] == 'I' && k-val1 >= 2) val1+=2;
	        else if(s[i] == 'I' && k-val2 >= 2) val2+=2;
	        else if(s[i] == 'G' && k-val2 >= 1 ) val2++;
	        else{
	            flag = 1;
	        }
	    }
	    
	    if(flag) cout << "NO\n";
	    else cout << "YES\n";
	}

}
